-- Bus Permits 2026 Sep Database Migration
-- Regional Transport Authority (RTA / क्षेत्रीय परिवहन प्राधिकार), Saran Division, Chapra
-- Notice Date: 09.09.2026
-- Applications 1 to 30

SET FOREIGN_KEY_CHECKS = 0;

CREATE TABLE IF NOT EXISTS `vehicle` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `application_no` INT NOT NULL COMMENT 'Application Serial No (1-42)',
    `applicant_name` VARCHAR(150) NOT NULL COMMENT 'Applicant / Owner Name',
    `father_husband_name` VARCHAR(150) DEFAULT NULL COMMENT 'Father or Husband Name',
    `address` TEXT DEFAULT NULL COMMENT 'Applicant Full Address',
    `registration_number` VARCHAR(50) NOT NULL COMMENT 'Bus Registration Number',
    `vehicle_type` VARCHAR(50) DEFAULT 'Bus' COMMENT 'Make / Type of Vehicle',
    `seating_capacity` VARCHAR(20) DEFAULT NULL COMMENT 'Seating Capacity e.g. 28+1, 32+1, 41, 48',
    `model_year` VARCHAR(20) DEFAULT NULL COMMENT 'Model Year e.g. 2009, 2011, 2014, 2024, 2026',
    `route_no` VARCHAR(50) DEFAULT NULL COMMENT 'Permit Route Number e.g. 2199, 4077 DN, 3826 DN',
    `route_name` VARCHAR(255) DEFAULT NULL COMMENT 'Route Start to End Name',
    `route_description` TEXT DEFAULT NULL COMMENT 'Full route details with via points and trips',
    `origin` VARCHAR(100) DEFAULT NULL COMMENT 'Origin City / Town',
    `destination` VARCHAR(100) DEFAULT NULL COMMENT 'Destination City / Town',
    `via` TEXT DEFAULT NULL COMMENT 'Intermediate Via Points',
    `trips_per_day` VARCHAR(100) DEFAULT NULL COMMENT 'Daily Trips (खेप)',
    `total_distance_km` DECIMAL(8,2) DEFAULT NULL COMMENT 'Total Distance in KM',
    `speed_range` VARCHAR(100) DEFAULT '20 से 60 किमी/घंटा' COMMENT 'Operating Speed Range',
    `is_nationalized` VARCHAR(100) DEFAULT '40 किमी के अंतर्गत' COMMENT 'Nationalization Status',
    `authority` VARCHAR(150) DEFAULT 'कार्यालय क्षेत्रीय परिवहन प्राधिकार, सारण, छपरा' COMMENT 'Issuing RTA Authority',
    `notice_date` DATE DEFAULT '2026-09-09' COMMENT 'Publication Notice Date',
    `pdf_page` INT DEFAULT NULL COMMENT 'Source Page in Bus Permit PDF',
    `status` ENUM('PROPOSED','PENDING_OBJECTION','APPROVED','REJECTED') DEFAULT 'PROPOSED',
    `created_at` TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    UNIQUE KEY `uniq_app_reg` (`application_no`, `registration_number`),
    KEY `idx_route_no` (`route_no`),
    KEY `idx_reg_no` (`registration_number`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

CREATE TABLE IF NOT EXISTS `vehicle_timetable` (
    `id` INT AUTO_INCREMENT PRIMARY KEY,
    `vehicle_id` INT NOT NULL COMMENT 'Foreign Key -> vehicle.id',
    `trip_number` INT DEFAULT 1 COMMENT 'Trip Number (1st trip, 2nd trip, etc.)',
    `trip_direction` VARCHAR(20) DEFAULT 'DOWN' COMMENT 'Direction: UP, DOWN, RETURN',
    `stop_order` INT NOT NULL COMMENT 'Stop Sequence Order (1, 2, 3...)',
    `stop_name` VARCHAR(150) NOT NULL COMMENT 'Bus Stop / Stage Point Name',
    `arrival_time` TIME DEFAULT NULL COMMENT 'Arrival Time (HH:MM:SS), NULL for origin',
    `departure_time` TIME DEFAULT NULL COMMENT 'Departure Time (HH:MM:SS), NULL for destination',
    `arrival_time_formatted` VARCHAR(20) DEFAULT NULL COMMENT 'Original formatted string e.g. 06:09',
    `departure_time_formatted` VARCHAR(20) DEFAULT NULL COMMENT 'Original formatted string e.g. 05:45',
    `halt_duration_minutes` INT DEFAULT 0 COMMENT 'Halt duration in minutes',
    `distance_km` DECIMAL(6,2) DEFAULT 0.00 COMMENT 'Distance from previous stop in KM',
    `travel_time` VARCHAR(50) DEFAULT NULL COMMENT 'Time taken from previous stop formatted string',
    `travel_time_minutes` INT DEFAULT 0 COMMENT 'Travel duration in minutes',
    `speed_kmph` VARCHAR(50) DEFAULT NULL COMMENT 'Running Speed in KM/H',
    `remarks` VARCHAR(255) DEFAULT NULL,
    KEY `idx_timetable_vehicle` (`vehicle_id`),
    KEY `idx_stop_name` (`stop_name`),
    CONSTRAINT `fk_timetable_vehicle` FOREIGN KEY (`vehicle_id`) REFERENCES `vehicle` (`id`) ON DELETE CASCADE
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

TRUNCATE TABLE `vehicle_timetable`;
TRUNCATE TABLE `vehicle`;

